contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address claimer) public payable {
        uint256 lowerBound = c.numRoundsClaimed(claimer);
        uint256 currentRoundId = c.roundId();
        uint256 expected = 0;
        for (uint256 currentRound = lowerBound; currentRound < currentRoundId; currentRound++) {
            uint256 winnersLength = 2;
            for (uint256 j = 0; j < winnersLength; j++) {
                if (c.winnerAddresses(currentRound, j) == claimer) {
                    expected += 1;
                }
            }
        }
        uint256 actual = c.getUnclaimedRewards(claimer);
        assert(actual == expected);
    }

    receive() external payable {}
}

