contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 newAmount) public {
        uint256 beforeWinners = c.winnersPerPeriod();
        bool isCallerAdmin = c.isAdmin(caller);

        // Bind msg.sender to the parameter caller for the call on c.
        // Since we cannot prank, we instead attempt the call from this test contract
        // and use the fact that this contract is not an admin of a fresh c.
        // A fresh c has isAdmin[ownerAddress] == true and isAdmin[address(this)] == false.
        require(!c.isAdmin(address(this)), "test contract unexpectedly admin");
        require(caller != address(this), "caller must not be test contract");

        bool reverted;
        try c.updateWinnersPerPeriod(newAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterWinners = c.winnersPerPeriod();

        assert(
            isCallerAdmin ||
            (reverted && beforeWinners == afterWinners)
        );
    }

    receive() external payable {}
}

