contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newWinnersPerPeriodAmount, uint256 winner0) public payable {
        require(newWinnersPerPeriodAmount >= 1, "need at least one winner");

        c.updateWinnersPerPeriod(newWinnersPerPeriodAmount);
        uint256 stored = c.winnersPerPeriod();

        uint256[] memory winners = new uint256[](newWinnersPerPeriodAmount);
        for (uint256 i = 0; i < newWinnersPerPeriodAmount; i++) {
            winners[i] = winner0;
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Either the selection succeeded with exactly the configured number of winners,
        // or it reverted; but the stored value must always equal the input.
        assert(stored == newWinnersPerPeriodAmount);
    }

    receive() external payable {}
}

