contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(string[] calldata modelURIs, string[] calldata modelTypes) public {
        uint32 before = c.numRoundsClaimed(address(this));
        bool reverted;
        if (modelURIs.length > 0) {
            try c.claimRewards(modelURIs, modelTypes, new uint256[2][](modelURIs.length)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool ok, ) = address(c).call(
                abi.encodeWithSignature("claimRewards(string[],string[],uint256[2][])", modelURIs, modelTypes, new uint256[2][](0))
            );
            reverted = !ok;
        }
        uint32 afterClaim = c.numRoundsClaimed(address(this));

        if (before == afterClaim) {
            assert(reverted == true || modelURIs.length == 0);
        }
    }
}

