contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winner0) public {
        require(winner0 != 0);

        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        uint256 roundIdBefore = c.roundId();

        uint256[] memory winners = new uint256[](winnersPerPeriodBefore);
        for (uint256 i = 0; i < winnersPerPeriodBefore; i++) {
            winners[i] = winner0 + i;
        }

        c.pickWinner(winners);

        uint256 roundIdAfter = c.roundId();
        bool selectionCompleteAfter = c.isSelectionComplete(roundIdBefore);

        assert(
            roundIdAfter == roundIdBefore + 1 &&
            selectionCompleteAfter &&
            c.winnerAddresses(roundIdBefore, 0) != address(0) &&
            c.fighterPoints(winner0) == 0
        );
    }
}

