contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[2] calldata winners) public payable {
        // Setup: make this test contract the owner/admin of c and record the two winners.
        c.adjustAdminAccess(address(this), true);

        uint256 w0 = winners[0];
        uint256 w1 = winners[1];
        require(w0 != w1);

        uint256[2] memory winnerIds = [w0, w1];

        // Adding points is the only way to make rewards non-trivial; they are cleared by pickWinner.
        c.addPoints(w0, 5);
        c.addPoints(w1, 7);
        c.addPoints(w0, 11);
        c.addPoints(w1, 13);

        uint256 beforeW0Points = c.fighterPoints(w0);
        uint256 beforeW1Points = c.fighterPoints(w1);
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 beforeRoundId = c.roundId();

        uint256[] memory selectedWinners = new uint256[](2);
        selectedWinners[0] = w0;
        selectedWinners[1] = w1;
        c.pickWinner(selectedWinners);

        // General rule: a full pickWinner call must clear each winner's recorded points,
        // subtract them from the total, and return exactly the picked winner ids as the
        // stored winner list for the round that was just closed.
        uint256 afterW0Points = c.fighterPoints(w0);
        uint256 afterW1Points = c.fighterPoints(w1);
        uint256 afterTotalPoints = c.totalPoints();
        uint256 afterRoundId = c.roundId();

        bool roundAdvanced = afterRoundId == beforeRoundId + 1;
        bool previousRoundSelected = c.isSelectionComplete(beforeRoundId);
        bool winner0Cleared = afterW0Points == 0;
        bool winner1Cleared = afterW1Points == 0;
        uint256 expectedRemainingPoints = beforeTotalPoints - beforeW0Points - beforeW1Points;
        bool totalPointsCorrect = afterTotalPoints == expectedRemainingPoints;

        address recorded0 = c.winnerAddresses(beforeRoundId, 0);
        address recorded1 = c.winnerAddresses(beforeRoundId, 1);
        uint256 len = c.winnerAddresses(beforeRoundId, 0).length;
        bool bothRecorded = len == 2;

        assert(
            roundAdvanced &&
            previousRoundSelected &&
            winner0Cleared &&
            winner1Cleared &&
            totalPointsCorrect &&
            bothRecorded &&
            recorded0 != address(0) &&
            recorded1 != address(0)
        );
    }

    receive() external payable {}
}

