contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points) public payable {
        // The test contract is the deployer/owner, so we can set the ranked battle address to this
        // test contract itself; then addPoints will accept our calls.
        c.transferOwnership(address(this));
        // We cannot call a private setter, but addPoints requires msg.sender == _rankedBattleAddress.
        // To make msg.sender == _rankedBattleAddress, we must have previously set _rankedBattleAddress.
        // Since we cannot set it directly, we instead use the constructor assumption: we deploy C
        // with rankedBattleAddress = address(this) in the checker? The template says the checker
        // deploys a FRESH c and this contract deployed c. The constructor of C took rankedBattleAddress.
        // We cannot change it. But if we are the deployer, we could have passed address(this) as the
        // ranked battle address. However, the checker controls deployment. To be safe, we just call
        // addPoints and handle the revert; but we want a general rule that holds for all inputs.
        // If addPoints reverts, we cannot observe the state change. The rule should account for that.

        uint256 totalBefore = c.totalPoints();
        uint256 pointsBefore = c.fighterPoints(tokenId);

        bool reverted;
        try c.addPoints(tokenId, points) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalPoints();
        uint256 pointsAfter = c.fighterPoints(tokenId);

        // General rule: If addPoints did not revert, then the fighter's points increased by exactly
        // `points` and totalPoints increased by exactly `points`. If it reverted, both values must
        // remain unchanged.
        if (!reverted) {
            assert(pointsAfter == pointsBefore + points && totalAfter == totalBefore + points);
        } else {
            assert(pointsAfter == pointsBefore && totalAfter == totalBefore);
        }
    }

    receive() external payable {}
}

