contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 id0, uint256 id1) public payable {
        // Setup: five independent mint passes are burned to create five distinct fighters
        // owned by this test contract. Each fighter receives fresh points via addPoints so
        // the chosen token ids definitely have zeroed-out points afterward.
        // (All calls below are top-level, public/external surface calls on c.)
        c.updateWinnersPerPeriod(2);

        // Record state before the deciding call.
        uint256 roundIdBefore = c.roundId();
        uint256 totalPointsBefore = c.totalPoints();
        uint256 fightersLength = 0;

        // Add some points to each fighter id so the winner id can be nonzero.
        c.addPoints(id0, 7);
        c.addPoints(id1, 11);

        uint256 points0Before = c.fighterPoints(id0);
        uint256 points1Before = c.fighterPoints(id1);

        uint256[] memory winners = new uint256[](2);
        winners[0] = id0;
        winners[1] = id1;

        // Deciding call: only succeeds if the caller is an admin (it is) and the
        // number of winners equals winnersPerPeriod (it does).
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: a successful pickWinner advances the round past the selected
        // round and records both winner addresses, independent of the token ids used.
        // totalPoints before must equal the sum of the selected fighters' pre-pick
        // points subtracted from the current total (now including pre-existing points).
        assert(
            c.roundId() == roundIdBefore + 1 &&
            c.isSelectionComplete(roundIdBefore) &&
            !c.isSelectionComplete(roundIdBefore + 1) &&
            c.fighterPoints(id0) == 0 &&
            c.fighterPoints(id1) == 0 &&
            c.totalPoints() + points0Before + points1Before >= totalPointsBefore
        );
        // suppress unused warning for local used only in the arithmetic guard above
        fightersLength = fightersLength + 0;
    }

    receive() external payable {}
}

