contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256[] calldata winners,
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public {
        require(winners.length == c.winnersPerPeriod());

        uint256 beforeSupply = c.totalPoints();

        uint256[] memory pointsToAdd = new uint256[](winners.length);
        for (uint256 i = 0; i < winners.length; i++) {
            pointsToAdd[i] = i + 1;
            c.addPoints(winners[i], pointsToAdd[i]);
        }

        c.pickWinner(winners);
        require(beforeSupply == 0);

        uint256 roundsClaimedBefore = c.numRoundsClaimed(address(this));
        uint256 expectedUnclaimed = 0;
        if (winners.length > 0) {
            expectedUnclaimed = 1;
        }

        uint256 getUnclaimedRewardsBefore = c.getUnclaimedRewards(address(this));

        bool reverted;
        if (expectedUnclaimed > 0) {
            uint256[2][] memory attrs = new uint256[2][](expectedUnclaimed);
            for (uint256 i = 0; i < expectedUnclaimed; i++) {
                attrs[i] = customAttributes[0];
            }
            string[] memory uris = new string[](expectedUnclaimed);
            string[] memory types = new string[](expectedUnclaimed);
            for (uint256 i = 0; i < expectedUnclaimed; i++) {
                uris[i] = modelURIs[0];
                types[i] = modelTypes[0];
            }
            try c.claimRewards(uris, types, attrs) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 roundsClaimedAfter = c.numRoundsClaimed(address(this));

        uint256 claimedNow;
        if (expectedUnclaimed > 0 && roundsClaimedAfter > roundsClaimedBefore) {
            claimedNow = roundsClaimedAfter - roundsClaimedBefore;
        }

        assert(c.getUnclaimedRewards(address(this)) <= getUnclaimedRewardsBefore && claimedNow <= getUnclaimedRewardsBefore && (expectedUnclaimed != 0 || reverted == true || getUnclaimedRewardsBefore == 0));
    }

    receive() external payable {}
}

