contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address candidate, bool wantAdmin, uint256 newWinnersPerPeriod) public {
        address originalOwner = c._ownerAddress();
        uint256 originalWinners = c.winnersPerPeriod();

        bool callReverted;
        bool ownerChanged;
        bool adminChanged;
        bool configChanged;

        if (caller != originalOwner) {
            try c.adjustAdminAccess(candidate, wantAdmin) {
                callReverted = false;
            } catch {
                callReverted = true;
            }

            require(callReverted, "non-owner adjustAdminAccess should always revert");

            bool adminBefore = c.isAdmin(candidate);

            adminChanged = (c.isAdmin(candidate) != adminBefore) || (c.isAdmin(candidate) != wantAdmin);

            ownerChanged = (c._ownerAddress() != originalOwner);
            configChanged = (c.winnersPerPeriod() != originalWinners);

            assert(
                c._ownerAddress() == originalOwner &&
                c.winnersPerPeriod() == originalWinners &&
                c.isAdmin(candidate) == adminBefore &&
                !adminChanged &&
                !ownerChanged &&
                !configChanged
            );
        } else {
            c.adjustAdminAccess(candidate, wantAdmin);
            assert(c.isAdmin(candidate) == wantAdmin && c._ownerAddress() == originalOwner && c.winnersPerPeriod() == originalWinners);
        }
    }
}

